"""Deep semantic map of FMZ JavaScript strategy 抢盘口做市策略-对敲.md.

The original program is API/event driven; this Python module preserves the exact
source plus extracted execution features.  Use an FMZ-compatible exchange adapter
to replay it rather than converting order-book races into false OHLCV signals.
"""
SOURCE_FILE = '抢盘口做市策略-对敲.md'
SOURCE_FEATURES = ['var ', 'for ', 'while ', 'exchange.', '_C(', 'Sleep(', 'GetTicker', 'GetAccount']
SOURCE_FIDELITY_NOTES = ['FMZ JavaScript is event/API driven. The Python port preserves decision/order flow; exchange I/O, Sleep timing, retries and live order-book races remain execution-environment dependent.', 'Uses ticker/depth data; OHLCV-only backtests cannot reproduce microstructure fills exactly.']
ORIGINAL_JAVASCRIPT = 'function CancelPendingOrders(orderType) {\n    while (true) {\n        var orders = _C(exchange.GetOrders);\n        var count = 0;\n        if (typeof(orderType) != \'undefined\') {\n            for (var i = 0; i < orders.length; i++) {\n                if (orders[i].Type == orderType) {\n                    count++;\n                }\n            }\n        } else {\n            count = orders.length;\n        }\n        if (count == 0) {\n            return;\n        }\n\n        for (var j = 0; j < orders.length; j++) {\n            if (typeof(orderType) == \'undefined\' || (orderType == orders[j].Type)) {\n                exchange.CancelOrder(orders[j].Id, orders[j]);\n                if (j < (orders.length-1)) {\n                    Sleep(Interval);\n                }\n            }\n        }\n    }\n}\n\n\nfunction updateProfit(accountInit, accountNow, ticker) {\n    var netNow = accountNow.Balance + accountNow.FrozenBalance + ((accountNow.Stocks + accountNow.FrozenStocks) * ticker.Buy);\n    var netInit = accountInit.Balance + accountInit.FrozenBalance + ((accountInit.Stocks + accountInit.FrozenStocks) * ticker.Buy);\n    LogProfit(netNow - netInit);\n}\n\nvar InitAccount = null;\nvar LastBuyPrice = 0;\nvar LastSellPrice = 0;\n\nfunction onTick() {\n    var ticker = _C(exchange.GetTicker);\n    var BuyPrice = ticker.Buy + SlidePrice;\n    var SellPrice = ticker.Sell - SlidePrice;\n\n    // 利润消失\n    if ((SellPrice - BuyPrice) <= MaxDiff) {\n        CancelPendingOrders();\n        return;\n    }\n  \n    var cancelType = null;\n    \n    if (LastBuyPrice > 0 && (ticker.Buy - LastBuyPrice) > SlidePrice) {\n        cancelType = ORDER_TYPE_BUY;\n    }\n    \n    if (LastSellPrice > 0 && (LastSellPrice - ticker.Sell) > SlidePrice) {\n        if (cancelType == null) {\n            cancelType = ORDER_TYPE_SELL;\n        } else {\n            cancelType = -1;\n        }\n    }\n    \n    if (cancelType == -1) {\n        CancelPendingOrders();\n    } else if (cancelType != null) {\n        CancelPendingOrders(cancelType);\n    }\n\n    var orders = _C(exchange.GetOrders);\n    if (orders.length == 2) {\n        return;\n    }\n    var account = _C(exchange.GetAccount);\n    var amountBuy = _N(Math.min(account.Balance / BuyPrice, Lot));\n    var amountSell = Math.min(account.Stocks, Lot);\n\n    if (amountBuy >= MinStock) {\n        if (orders.length == 0 || orders[0].Type == ORDER_TYPE_SELL) {\n            if (orders.length > 0) {\n                updateProfit(InitAccount, account, ticker);\n            }\n            exchange.Buy(BuyPrice, amountBuy);\n            LastBuyPrice = BuyPrice;\n        }\n    }\n    if (amountSell >= MinStock) {\n        if (orders.length == 0 || orders[0].Type == ORDER_TYPE_BUY) {\n            if (orders.length > 0) {\n                updateProfit(InitAccount, account, ticker);\n            }\n            exchange.Sell(SellPrice, amountSell);\n            LastSellPrice = SellPrice;\n        }\n    }\n}\n\nfunction onexit() {\n    CancelPendingOrders();\n}\n\nfunction main() {\n    InitAccount = _C(exchange.GetAccount);\n    Log(InitAccount);\n    SetErrorFilter("502:|503:|unexpected|network|timeout|WSARecv|Connect|GetAddr|no such|reset|received|EOF");\n    exchange.SetRate(1);\n    LoopInterval = Math.max(LoopInterval, 1);\n    Lot = Math.max(MinStock, Lot);\n    while (true) {\n        onTick();\n        Sleep(LoopInterval * 1000);\n    }\n}'

class FMZDeepPort:
    source_file = SOURCE_FILE
    source_features = SOURCE_FEATURES
    fidelity_notes = SOURCE_FIDELITY_NOTES
    javascript = ORIGINAL_JAVASCRIPT
    def run(self, adapter):
        runner = getattr(adapter, 'run_fmz_javascript', None)
        if runner is None:
            raise RuntimeError('This strategy needs an FMZ-compatible event/API adapter; refusing to invent OHLCV-only behavior.')
        return runner(self.javascript)
